 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # A solid cross marks the boundaries of a motif tile. Repeat the motif
    # into each of the other tile regions, retaining the cross.
    sep = 4
    rows = [r for r in range(h) if all(v == sep for v in grid[r])]
    cols = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]
    if not rows or not cols:
        return [row[:] for row in grid]
    sr, sc = rows[0], cols[0]
    row_ranges = [(0, sr), (sr + 1, h)]
    col_ranges = [(0, sc), (sc + 1, w)]
    out = [row[:] for row in grid]
    for r0, r1 in row_ranges:
        for c0, c1 in col_ranges:
            if r0 == 0 and c0 == 0:
                continue
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = grid[r % sr][c % sc]
    return out
